// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAgents Usuarios de la agencia. Solo a los activos se les asigna cartera; requiere manage o assign.
	// (GET /api/v1/policies/agents)
	ListAgents(ctx context.Context, request ListAgentsRequestObject) (ListAgentsResponseObject, error)

	// (GET /api/v1/policies/policies)
	ListPolicies(ctx context.Context, request ListPoliciesRequestObject) (ListPoliciesResponseObject, error)
	// CreatePolicy Registra una póliza en cotización (expedición manual).
	// (POST /api/v1/policies/policies)
	CreatePolicy(ctx context.Context, request CreatePolicyRequestObject) (CreatePolicyResponseObject, error)

	// (GET /api/v1/policies/policies/{policyId})
	GetPolicy(ctx context.Context, request GetPolicyRequestObject) (GetPolicyResponseObject, error)
	// UpdatePolicyTerms Ajusta los datos antes de expedir.
	// (PUT /api/v1/policies/policies/{policyId})
	UpdatePolicyTerms(ctx context.Context, request UpdatePolicyTermsRequestObject) (UpdatePolicyTermsResponseObject, error)
	// AcceptPolicy El cliente aceptó; pasa a trámite con la aseguradora.
	// (POST /api/v1/policies/policies/{policyId}/accept)
	AcceptPolicy(ctx context.Context, request AcceptPolicyRequestObject) (AcceptPolicyResponseObject, error)
	// ReassignPolicyAgent Cambia el asesor de la póliza por otro activo. Queda en el historial con motivo.
	// (POST /api/v1/policies/policies/{policyId}/agent)
	ReassignPolicyAgent(ctx context.Context, request ReassignPolicyAgentRequestObject) (ReassignPolicyAgentResponseObject, error)
	// CancelPolicy Registra la cancelación que expidió la aseguradora.
	// (POST /api/v1/policies/policies/{policyId}/cancel)
	CancelPolicy(ctx context.Context, request CancelPolicyRequestObject) (CancelPolicyResponseObject, error)
	// RequestEndorsement Registra una solicitud de endoso (Flujo 5).
	// (POST /api/v1/policies/policies/{policyId}/endorsements)
	RequestEndorsement(ctx context.Context, request RequestEndorsementRequestObject) (RequestEndorsementResponseObject, error)
	// IssueEndorsement Registra el endoso emitido por la aseguradora y aplica sus efectos.
	// (POST /api/v1/policies/policies/{policyId}/endorsements/{endorsementId}/issue)
	IssueEndorsement(ctx context.Context, request IssueEndorsementRequestObject) (IssueEndorsementResponseObject, error)

	// (POST /api/v1/policies/policies/{policyId}/endorsements/{endorsementId}/reject)
	RejectEndorsement(ctx context.Context, request RejectEndorsementRequestObject) (RejectEndorsementResponseObject, error)
	// IssuePolicy Registra la póliza expedida por la aseguradora. Exige KYC si module.compliance está encendido.
	// (POST /api/v1/policies/policies/{policyId}/issue)
	IssuePolicy(ctx context.Context, request IssuePolicyRequestObject) (IssuePolicyResponseObject, error)
	// RejectPolicy La aseguradora rechazó la solicitud.
	// (POST /api/v1/policies/policies/{policyId}/reject)
	RejectPolicy(ctx context.Context, request RejectPolicyRequestObject) (RejectPolicyResponseObject, error)
	// TransferPortfolio Pide pasar toda la cartera de un asesor a otro. Se procesa en segundo plano.
	// (POST /api/v1/policies/portfolio-transfers)
	TransferPortfolio(ctx context.Context, request TransferPortfolioRequestObject) (TransferPortfolioResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

